{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The flow-log bucket has no bucket-level Public Access Block, allowing future ACL or bucket-policy changes to expose sensitive network logs publicly."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is not enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "Without versioning, flow-log objects can be permanently overwritten or deleted, reducing their availability for security investigations."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not enforce KMS encryption",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly require KMS-backed default encryption for potentially sensitive flow-log data."
    },
    {
      "check_id": "UNKNOWN",
      "title": "S3 bucket permits forced destruction",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Setting force_destroy to true allows Terraform to delete the bucket together with all flow-log objects and versions, increasing the risk of irreversible audit-log loss."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = false
  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }

    bucket_key_enabled = true
  }
}
",
  "fix_summary": "Added a complete S3 Public Access Block, enabled versioning, and configured KMS-backed default encryption with bucket keys. Disabled forced bucket destruction to reduce the risk of irreversible flow-log loss."
}
